"use client"

import { useState, type FormEvent } from "react"
import { useConvexMutation } from "@convex-dev/react-query"
import { useMutation } from "@tanstack/react-query"
import { Delete02Icon, Edit01Icon } from "@hugeicons/core-free-icons"
import { HugeiconsIcon } from "@hugeicons/react"

import { api } from "@/convex/_generated/api"
import type { Id } from "@/convex/_generated/dataModel"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@workspace/ui/components/alert-dialog"
import { Button } from "@workspace/ui/components/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@workspace/ui/components/dialog"
import {
  Field,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@workspace/ui/components/field"
import { Input } from "@workspace/ui/components/input"
import { Spinner } from "@workspace/ui/components/spinner"

type ClientRecord = {
  _id: Id<"clients">
  email?: string
  name: string
}

export function ClientRecordActions({
  client,
  workspaceId,
}: {
  client: ClientRecord
  workspaceId: Id<"workspaces">
}) {
  return (
    <div className="flex gap-2">
      <EditClientDialog client={client} workspaceId={workspaceId} />
      <DeleteClientDialog client={client} workspaceId={workspaceId} />
    </div>
  )
}

function EditClientDialog({
  client,
  workspaceId,
}: {
  client: ClientRecord
  workspaceId: Id<"workspaces">
}) {
  const [open, setOpen] = useState(false)
  const [name, setName] = useState(client.name)
  const [email, setEmail] = useState(client.email ?? "")
  const updateClient = useConvexMutation(api.clients.update)
  const mutation = useMutation({
    mutationFn: updateClient,
    onSuccess: () => setOpen(false),
  })

  function handleOpenChange(nextOpen: boolean) {
    setOpen(nextOpen)
    mutation.reset()

    if (nextOpen) {
      setName(client.name)
      setEmail(client.email ?? "")
    }
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const trimmedName = name.trim()

    if (trimmedName) {
      mutation.mutate({
        clientId: client._id,
        email: email.trim() || undefined,
        name: trimmedName,
        workspaceId,
      })
    }
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogTrigger render={<Button size="sm" variant="outline" />}>
        <HugeiconsIcon
          data-icon="inline-start"
          icon={Edit01Icon}
          strokeWidth={2}
        />
        Edit
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Edit client</DialogTitle>
          <DialogDescription>
            Update the name and email used for this client.
          </DialogDescription>
        </DialogHeader>
        <form className="flex flex-col gap-4" onSubmit={handleSubmit}>
          <FieldGroup>
            <Field data-invalid={mutation.isError || undefined}>
              <FieldLabel htmlFor={`client-name-${client._id}`}>
                Client name
              </FieldLabel>
              <Input
                aria-invalid={mutation.isError || undefined}
                autoComplete="name"
                autoFocus
                id={`client-name-${client._id}`}
                maxLength={120}
                onChange={(event) => setName(event.target.value)}
                required
                value={name}
              />
            </Field>
            <Field data-invalid={mutation.isError || undefined}>
              <FieldLabel htmlFor={`client-email-${client._id}`}>
                Email
              </FieldLabel>
              <Input
                aria-invalid={mutation.isError || undefined}
                autoComplete="email"
                id={`client-email-${client._id}`}
                maxLength={254}
                onChange={(event) => setEmail(event.target.value)}
                type="email"
                value={email}
              />
              {mutation.isError ? (
                <FieldError>
                  {getErrorMessage(
                    mutation.error,
                    "Could not update the client."
                  )}
                </FieldError>
              ) : null}
            </Field>
          </FieldGroup>
          <Button disabled={!name.trim() || mutation.isPending} type="submit">
            {mutation.isPending ? <Spinner data-icon="inline-start" /> : null}
            {mutation.isPending ? "Saving changes" : "Save changes"}
          </Button>
        </form>
      </DialogContent>
    </Dialog>
  )
}

function DeleteClientDialog({
  client,
  workspaceId,
}: {
  client: ClientRecord
  workspaceId: Id<"workspaces">
}) {
  const [open, setOpen] = useState(false)
  const removeClient = useConvexMutation(api.clients.remove)
  const mutation = useMutation({
    mutationFn: removeClient,
    onSuccess: () => setOpen(false),
  })

  function handleOpenChange(nextOpen: boolean) {
    setOpen(nextOpen)
    mutation.reset()
  }

  return (
    <AlertDialog open={open} onOpenChange={handleOpenChange}>
      <AlertDialogTrigger render={<Button size="sm" variant="ghost" />}>
        <HugeiconsIcon
          data-icon="inline-start"
          icon={Delete02Icon}
          strokeWidth={2}
        />
        Delete
      </AlertDialogTrigger>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Delete {client.name}?</AlertDialogTitle>
          <AlertDialogDescription>
            This cannot be undone. A client with galleries must have those
            galleries deleted first.
          </AlertDialogDescription>
        </AlertDialogHeader>
        {mutation.isError ? (
          <p className="text-xs/relaxed text-destructive" role="alert">
            {getErrorMessage(mutation.error, "Could not delete the client.")}
          </p>
        ) : null}
        <AlertDialogFooter>
          <AlertDialogCancel disabled={mutation.isPending}>
            Cancel
          </AlertDialogCancel>
          <AlertDialogAction
            disabled={mutation.isPending}
            onClick={() =>
              mutation.mutate({ clientId: client._id, workspaceId })
            }
            variant="destructive"
          >
            {mutation.isPending ? <Spinner data-icon="inline-start" /> : null}
            {mutation.isPending ? "Deleting client" : "Delete client"}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

function getErrorMessage(error: unknown, fallback: string) {
  return error instanceof Error ? error.message : fallback
}

