export function ClientsView({ workspaceId }: { workspaceId: string }) {
  const typedWorkspaceId = workspaceId as Id<"workspaces">
  const clientsQuery = useQuery(
    convexQuery(api.clients.list, { workspaceId: typedWorkspaceId })
  )

  return (
    <div className="mx-auto flex w-full max-w-6xl flex-col gap-8">
      <header className="flex items-end justify-between gap-4">
        <div className="flex flex-col gap-1">
          <h1 className="font-heading text-2xl font-medium tracking-tight">
            Clients
          </h1>
          <p className="text-sm text-muted-foreground">
            Keep each client and their galleries together.
          </p>
        </div>
        <CreateClientDialog workspaceId={typedWorkspaceId} />
      </header>

      {clientsQuery.isPending ? (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {Array.from({ length: 3 }, (_, index) => (
            <Skeleton className="h-32 rounded-lg" key={index} />
          ))}
        </div>
      ) : clientsQuery.isError ? (
        <Empty className="min-h-96 border bg-card">
          <EmptyHeader>
            <EmptyMedia variant="icon">
              <HugeiconsIcon icon={Alert02Icon} strokeWidth={2} />
            </EmptyMedia>
            <EmptyTitle>Clients unavailable</EmptyTitle>
            <EmptyDescription>
              Client records could not be loaded. Try again in a moment.
            </EmptyDescription>
          </EmptyHeader>
        </Empty>
      ) : clientsQuery.data.length === 0 ? (
        <Empty className="min-h-96 border bg-card">
          <EmptyHeader>
            <EmptyMedia variant="icon">
              <HugeiconsIcon icon={UserMultipleIcon} strokeWidth={1.8} />
            </EmptyMedia>
            <EmptyTitle>No clients yet</EmptyTitle>
            <EmptyDescription>
              Add the first client before creating a gallery for them.
            </EmptyDescription>
          </EmptyHeader>
        </Empty>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {clientsQuery.data.map((client) => (
            <Card key={client._id}>
              <CardHeader>
                <CardTitle>{client.name}</CardTitle>
                <CardDescription>Client</CardDescription>
              </CardHeader>
              <CardContent className="text-muted-foreground">
                {client.email ?? "No email address"}
              </CardContent>
              <CardFooter>
                <ClientRecordActions
                  client={client}
                  workspaceId={typedWorkspaceId}
                />
              </CardFooter>
            </Card>
          ))}
        </div>
      )}
    </div>
  )
}

function CreateClientDialog({
  workspaceId,
}: {
  workspaceId: Id<"workspaces">
}) {
  const [open, setOpen] = useState(false)
  const [name, setName] = useState("")
  const [email, setEmail] = useState("")
  const createClient = useConvexMutation(api.clients.create)
  const mutation = useMutation({
    mutationFn: createClient,
    onSuccess: () => {
      setName("")
      setEmail("")
      setOpen(false)
    },
  })

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const trimmedName = name.trim()

    if (trimmedName) {
      mutation.mutate({
        email: email.trim() || undefined,
        name: trimmedName,
        workspaceId,
      })
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger render={<Button />}>
        <HugeiconsIcon
          data-icon="inline-start"
          icon={Add01Icon}
          strokeWidth={2}
        />
        New client
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Add a client</DialogTitle>
          <DialogDescription>
            Galleries for this workspace will stay grouped under this client.
          </DialogDescription>
        </DialogHeader>
        <form className="flex flex-col gap-4" onSubmit={handleSubmit}>
          <FieldGroup>
            <Field data-invalid={mutation.isError || undefined}>
              <FieldLabel htmlFor="client-name">Client name</FieldLabel>
              <Input
                aria-invalid={mutation.isError || undefined}
                autoComplete="name"
                autoFocus
                id="client-name"
                maxLength={120}
                onChange={(event) => setName(event.target.value)}
                placeholder="Taylor and Morgan"
                required
                value={name}
              />
            </Field>
            <Field data-invalid={mutation.isError || undefined}>
              <FieldLabel htmlFor="client-email">Email</FieldLabel>
              <Input
                aria-invalid={mutation.isError || undefined}
                autoComplete="email"
                id="client-email"
                maxLength={254}
                onChange={(event) => setEmail(event.target.value)}
                placeholder="client@example.com"
                type="email"
                value={email}
              />
              {mutation.isError ? (
                <FieldError>
                  {mutation.error instanceof Error
                    ? mutation.error.message
                    : "Could not add the client."}
                </FieldError>
              ) : null}
            </Field>
          </FieldGroup>
          <Button disabled={!name.trim() || mutation.isPending} type="submit">
            {mutation.isPending ? <Spinner data-icon="inline-start" /> : null}
            {mutation.isPending ? "Adding client" : "Add client"}
          </Button>
        </form>
      </DialogContent>
    </Dialog>
  )
}

import { v } from "convex/values"

import { mutation, query } from "./_generated/server"
import { requireWorkspaceMember } from "./lib/auth"
import { requirePaidWorkspace } from "./lib/billing"

export const list = query({
  args: {
    workspaceId: v.id("workspaces"),
  },
  handler: async (ctx, args) => {
    await requireWorkspaceMember(ctx, args.workspaceId)

    return await ctx.db
      .query("clients")
      .withIndex("by_workspace", (query) =>
        query.eq("workspaceId", args.workspaceId)
      )
      .order("desc")
      .take(100)
  },
})

export const create = mutation({
  args: {
    workspaceId: v.id("workspaces"),
    name: v.string(),
    email: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    await requirePaidWorkspace(ctx, args.workspaceId)

    const name = args.name.trim()
    const email = args.email?.trim() || undefined

    if (!name) {
      throw new Error("Client name is required")
    }

    return await ctx.db.insert("clients", {
      workspaceId: args.workspaceId,
      name,
      email,
    })
  },
})

export const update = mutation({
  args: {
    workspaceId: v.id("workspaces"),
    clientId: v.id("clients"),
    name: v.string(),
    email: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    await requirePaidWorkspace(ctx, args.workspaceId)

    const client = await ctx.db.get(args.clientId)

    if (!client || client.workspaceId !== args.workspaceId) {
      throw new Error("Client not found")
    }

    const name = args.name.trim()
    const email = args.email?.trim() || undefined

    if (!name) {
      throw new Error("Client name is required")
    }

    await ctx.db.patch(args.clientId, { name, email })
  },
})

export const remove = mutation({
  args: {
    workspaceId: v.id("workspaces"),
    clientId: v.id("clients"),
  },
  handler: async (ctx, args) => {
    await requirePaidWorkspace(ctx, args.workspaceId)

    const client = await ctx.db.get(args.clientId)

    if (!client || client.workspaceId !== args.workspaceId) {
      throw new Error("Client not found")
    }

    const gallery = await ctx.db
      .query("galleries")
      .withIndex("by_workspace_and_client", (query) =>
        query.eq("workspaceId", args.workspaceId).eq("clientId", args.clientId)
      )
      .first()

    if (gallery) {
      throw new Error(
        "Delete this client's galleries before deleting the client"
      )
    }

    await ctx.db.delete(args.clientId)
  },
})

